"""Tests for NoteEngine.key_up — shared polyphony/synthesis state management on key release."""

import sys
from unittest.mock import Mock, MagicMock, patch

import pytest

# Mock sounddevice before importing audio_logic to prevent real hardware access
with patch.dict(sys.modules, {'sounddevice': MagicMock()}):
    from audio_logic import NoteEngine, _Voice
    from key_mapping import frequency_for_key


def test_key_up_for_inactive_key_does_nothing():
    """Key up for a key that's neither active nor pending emits nothing."""
    # meridian: unit_id=ebf2a81ddbb1 requirement=4-1
    callback = Mock()
    engine = NoteEngine(on_state_change=callback)
    
    result = engine.key_up("a")
    
    assert result is None
    callback.assert_not_called()


def test_key_up_for_active_key_with_no_pending():
    """Releasing an active key emits one (key, False) event when no pending keys exist."""
    # meridian: unit_id=ebf2a81ddbb1 requirement=4-1
    callback = Mock()
    engine = NoteEngine(on_state_change=callback)
    
    # Manually add an active voice (bypassing key_down to control state directly)
    with engine._lock:
        engine._active["a"] = _Voice("a", frequency_for_key("a"))
    
    result = engine.key_up("a")
    
    assert result is None
    callback.assert_called_once_with("a", False)
    with engine._lock:
        assert "a" not in engine._active
        assert len(engine._releasing) == 1
        assert engine._releasing[0].key == "a"


def test_key_up_for_active_key_with_pending_keys():
    """Releasing an active key when pending keys exist emits (released, False) then (next_pending, True)."""
    # meridian: unit_id=ebf2a81ddbb1 requirement=4-1
    callback = Mock()
    engine = NoteEngine(on_state_change=callback)
    
    # Set up: one active key "a", one pending key "s"
    with engine._lock:
        engine._active["a"] = _Voice("a", frequency_for_key("a"))
        engine._pending.append("s")
    
    result = engine.key_up("a")
    
    assert result is None
    assert callback.call_count == 2
    callback.assert_any_call("a", False)
    callback.assert_any_call("s", True)
    
    with engine._lock:
        assert "a" not in engine._active
        assert "s" in engine._active
        assert len(engine._releasing) == 1
        assert engine._releasing[0].key == "a"
        assert "s" not in engine._pending


def test_key_up_for_pending_key_removes_from_pending():
    """Releasing a pending key removes it from the pending list without emitting events."""
    # meridian: unit_id=ebf2a81ddbb1 requirement=4-1
    callback = Mock()
    engine = NoteEngine(on_state_change=callback)
    
    # Set up: key "d" is pending
